function list(items:Task[]){return items.length?'<div class="task-list">'+items.map(x=>'<div class="task"><div><b>'+esc(x.name)+'</b><small>'+esc(x.category)+' · '+new Date(x.created).toLocaleString()+'</small></div><span class="status">Engine required</span></div>').join("")+'</div>':'<div class="empty">No production tasks yet.</div>';}
function moduleDesc(id:string){const d:Record<string,string>={explore:"Find a production workspace by task, review available tools and check what is ready to run.",cloud:"Create, organise and reopen projects with shared production records and media.",knowledge:"Collect research, source notes and references alongside the production they support.",series:"Organise multi-season productions, episode runtimes, scene plans and continuity bibles.",director:"Briefs, scripts, hooks, storyboards and shot plans.",canvas:"Connect steps into repeatable multi-engine workflows.",characters:"Reusable character bibles, voices and consent.",cinema:"Camera, lens, lighting, movement and continuity.",images:"Prompting, references, variations and image edits.",video:"Timeline, captions, audio, cutdowns and exports.",voice:"Narration, speech, transcription and dubbing.",enhance:"Upscale, restore, retouch, repair and cleanup.",campaigns:"Ads, UGC concepts, channel variants and batches.",library:"Source media, references and derived assets.",engines:"Provider-neutral adapters and capability readiness.",capabilities:"Search the complete capability registry, requirements and readiness.",provenance:"Inspect completed Content Credentials stages, test evidence and remaining release gates.",runtime:"Persistent projects, original media, local processing jobs and audit events.",readiness:"See what is merged, what is still in progress and which infrastructure gates block a complete release.",billing:"Manage subscription plans, mobile-money renewals, payment history and invoices.",finance:"Revenue intelligence, subscription economics, settlement reconciliation, risk queues and protected finance administration."};return d[id]||"Manage production.";}
