function cinema(){return header("SCENE DESIGN & CAMERA LANGUAGE","Cinematic studio","Plan shot-by-shot framing, lens, camera height, movement, lighting, blocking and continuity.",'<button class="primary" data-action="shot">＋ Add shot</button>')+'<div class="shot-grid">'+(state.shots.length?state.shots.map((s,i)=>'<article class="shot"><div class="shot-art"><span>SHOT '+(i+1)+'</span><b>'+esc(s.camera)+'</b></div><div class="shot-body"><b>'+esc(s.scene)+'</b><p>'+esc(s.action)+'</p><small>'+esc(s.lens)+' · '+esc(s.movement)+' · '+s.duration+' sec</small><button class="quiet" data-edit="'+s.id+'">Edit shot ↗</button></div></article>').join(""):'<div class="empty">Storyboard is empty. Add a shot to start directing.</div>')+'</div>'+panel("Camera controls","<p>Shot size · lens · focal length · camera height · movement · subject blocking · eyeline · key/fill/rim lighting · time of day · depth of field · motion intensity · first/last frame · reference strength · continuity.</p>");}
async function queueGenerationWorkflow(kind:"image.generate"|"video.generate",prompt:string,config:Record<string,unknown>){
 const approvalId=uid(),generationId=uid(),image=kind==="image.generate";
 const approvalNode={id:approvalId,kind:"approval",label:"Human approval · paid generation",inputs:[{id:"input",label:"Generation request",type:"any",required:true}],outputs:[{id:"result",label:"Approved prompt",type:"any"},{id:"approved",label:"Approval record",type:"structured-data"}],config:{input:prompt},position:{x:30,y:40}};
 const generationNode={id:generationId,kind,label:image?"Generate image":"Generate video",inputs:image?[{id:"prompt",label:"Prompt",type:"text",required:true},{id:"reference",label:"Reference",type:"image"}]:[{id:"prompt",label:"Prompt",type:"text",required:true},{id:"start-frame",label:"Start frame",type:"start-frame"},{id:"reference",label:"Reference",type:"video",multiple:true}],outputs:[{id:image?"image":"video",label:image?"Generated image":"Generated video",type:image?"image":"video"}],config,position:{x:380,y:40}};
 const graph:WorkflowGraph={id:uid(),projectId:"",revision:1,name:(image?"Image":"Video")+" generation · "+prompt.slice(0,48),nodes:[approvalNode as any,generationNode as any],edges:[{id:uid(),sourceNodeId:approvalId,sourcePortId:"result",targetNodeId:generationId,targetPortId:"prompt"}]};
 const saved=await apiRequest<{workflow:{id:string}}>("/api/workflows",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({name:graph.name,graph})});
 const run=await apiRequest<{runId:string;status:string}>("/api/workflows/"+saved.workflow.id+"/run",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({target:{kind:"all"}})});
 state.tab="canvas";render();
 await refreshWorkflowWorkspace("Generation workflow saved and queued. Review the request, then approve the human checkpoint before any paid provider call.");
 state.cloudMessage="Workflow "+run.runId+" · "+run.status+". No provider is called until the approval step is approved.";
}
