   const mapping={image:["imageCount","imageMinorPerImage"],video:["videoSeconds","videoMinorPerSecond"],render:["renderSeconds","renderMinorPerSecond"]} as const;
   const [quantityField,rateField]=mapping[operation as keyof typeof mapping];
   if(!provider||!model||!currency||!version||!Number.isFinite(quantity)||quantity<=0||!Number.isSafeInteger(rate)||rate<0||!Number.isSafeInteger(successfulOutputs)||successfulOutputs<1||!Number.isSafeInteger(marginBps)||!Number.isSafeInteger(feeBps))throw new Error("Complete the provider, model, currency, version, quantity and pricing assumptions with valid values.");
   financeState.workloadEstimate=null;render();
